<script setup lang="ts">
import type { SiteSettings, Page, Content } from '~/types'
import { sections } from '~/utils/site'
import { useMessage } from 'naive-ui'
definePageMeta({ layout: 'admin' }); useSeoMeta({ title: '系统设置' })
const api = useApi(), message = useMessage(), confirm = useConfirm(), { account, load } = useAuth()
const loaded = await api<{ settings: SiteSettings; lockVersion: number }>('/api/admin/site')
const settings = ref(loaded.settings), version = ref(loaded.lockVersion), snapshot = ref(JSON.stringify(loaded.settings)), busy = ref(false)
const displayName = ref(account.value?.displayName || ''), currentPassword = ref(''), newPassword = ref(''), repeatPassword = ref('')
const siteDirty = computed(() => snapshot.value !== JSON.stringify(settings.value))
const dirty = computed(() => siteDirty.value || displayName.value !== (account.value?.displayName || '') || !!currentPassword.value || !!newPassword.value || !!repeatPassword.value)
useUnsavedChanges(dirty)
async function save() { busy.value = true; try { const result = await api<typeof loaded>('/api/admin/site', { method: 'PUT', body: { settings: settings.value, lockVersion: version.value } }); version.value = result.lockVersion; snapshot.value = JSON.stringify(settings.value); await refreshNuxtData('site-settings'); message.success('网站信息已保存') } catch (e) { message.error(errorText(e)) } finally { busy.value = false } }
async function saveProfile() { try { await api('/api/admin/account/profile', { method: 'PUT', body: { displayName: displayName.value, lockVersion: account.value!.lockVersion } }); await load(); message.success('管理员资料已保存') } catch (e) { message.error(errorText(e)) } }
async function changePassword() {
  if (siteDirty.value || displayName.value !== account.value?.displayName) { message.warning('请先保存网站设置和管理员资料，再修改密码'); return }
  if (newPassword.value !== repeatPassword.value) { message.error('两次新密码不一致'); return }
  if (!await confirm('修改管理员密码？', '修改成功后，所有设备上的会话将失效，需要重新登录。')) return
  try { await api('/api/admin/account/password', { method: 'POST', body: { currentPassword: currentPassword.value, newPassword: newPassword.value, lockVersion: account.value!.lockVersion } }); currentPassword.value = ''; newPassword.value = ''; repeatPassword.value = ''; displayName.value = ''; account.value = null; message.success('密码已修改，请重新登录'); await navigateTo('/admin/login') } catch (e) { message.error(errorText(e)) }
}
async function exportContents() {
  busy.value = true
  try {
    const items: Content[] = []
    for (const status of ['all', 'trash']) { let page = 1, total = 0; do { const result = await api<Page<Content>>(`/api/admin/contents?status=${status}&page=${page}&size=50`); total = result.total; for (const item of result.items) items.push(await api(`/api/admin/contents/${item.id}`)); page++ } while ((page - 1) * 50 < total) }
    const payload = { exportedAt: new Date().toISOString(), format: 'caiya-content-export-v1', note: 'Current working revisions only; media binaries and frozen history require a full database and media backup.', site: (await api<typeof loaded>('/api/admin/site')).settings, taxonomy: await api('/api/admin/taxonomy'), contents: items }
    const url = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' })); const link = document.createElement('a'); link.href = url; link.download = `caiya-content-${new Date().toISOString().slice(0, 10)}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); message.success('内容导出已开始下载')
  } catch (e) { message.error(errorText(e)) } finally { busy.value = false }
}
</script>
<template><div><AdminPageHead title="系统设置" subtitle="把网站的名字、介绍和日常管理整理在这里。"><button class="primary" :disabled="busy || !dirty" @click="save">保存网站设置</button></AdminPageHead><div class="settings-grid"><section class="studio-panel"><h2>网站信息</h2><div class="field"><label for="site-name">站点名称</label><input id="site-name" v-model="settings.name" maxlength="80"></div><div class="field"><label for="site-description">站点描述</label><textarea id="site-description" v-model="settings.description" maxlength="300" rows="3" /></div><div class="two-fields"><div class="field"><label for="site-author">作者名称</label><input id="site-author" v-model="settings.author" maxlength="80"></div><div class="field"><label for="site-email">联系邮箱</label><input id="site-email" v-model="settings.email" type="email" maxlength="254"></div></div><div class="field"><label for="site-bio">关于我</label><textarea id="site-bio" v-model="settings.bio" maxlength="500" rows="4" /></div><div class="field"><label for="site-github">GitHub 地址</label><input id="site-github" v-model="settings.github" type="url" placeholder="https://github.com/…"></div><div class="field"><label for="site-footer">页脚文案</label><input id="site-footer" v-model="settings.footer" maxlength="300"></div><div class="field"><label for="site-icp">ICP 备案号</label><input id="site-icp" v-model="settings.icpNumber" maxlength="80" placeholder="如：桂ICP备2026024037号"><p class="admin-footnote">填写后显示在页脚，并链接到工信部备案查询。</p></div><div class="field"><label>首页展示栏目</label><div class="checkbox-group"><label v-for="s in sections" :key="s.type"><input v-model="settings.homeModules" type="checkbox" :value="s.type">{{ s.label }}</label></div></div><div class="settings-divider" /><h2>数据导出与备份</h2><p class="admin-footnote">导出当前工作版本、分类标签和网站设置，便于整理内容。图片文件和历史版本需要随数据库一起备份。</p><button :disabled="busy" @click="exportContents">导出内容 JSON</button><div class="help-note">完整备份与恢复：使用项目提供的备份脚本，同时保存数据库与上传目录。恢复前先在隔离环境验证。</div></section><aside class="settings-stack"><section class="studio-panel"><h2>管理员资料</h2><p class="admin-footnote">账号：{{ account?.username }}</p><form @submit.prevent="saveProfile"><div class="field"><label for="display-name">管理后台显示名</label><input id="display-name" v-model="displayName" required maxlength="80"></div><button>保存管理员资料</button></form></section><section class="studio-panel"><h2>修改密码</h2><form @submit.prevent="changePassword"><div class="field"><label for="current-password">当前密码</label><input id="current-password" v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="72"></div><div class="field"><label for="new-password">新密码</label><input id="new-password" v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="72"></div><div class="field"><label for="repeat-password">确认新密码</label><input id="repeat-password" v-model="repeatPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="72"></div><button>修改密码并重新登录</button></form><p class="admin-footnote">至少 12 位。修改后会退出所有设备上的登录。</p></section><section class="studio-panel"><h2>站点管理</h2><NuxtLink to="/admin/appearance" class="text-link">外观与阅读设置 →</NuxtLink><NuxtLink to="/admin/analytics" class="text-link">统计连接与访问数据 →</NuxtLink><NuxtLink to="/admin/logs" class="text-link">查看操作日志 →</NuxtLink></section></aside></div></div></template>
